from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = sorted(set(v for row in grid for v in row if v != bg))
    candidates = []

    for color in colors:
        # Prefix sums let us score every possible rectangular patch quickly.
        pref = [[0] * (w + 1) for _ in range(h + 1)]
        row_pref = [[0] * (w + 1) for _ in range(h)]
        col_pref = [[0] * w for _ in range(h + 1)]
        for r in range(h):
            run = 0
            for c in range(w):
                v = int(grid[r][c] == color)
                run += v
                row_pref[r][c + 1] = run
                col_pref[r + 1][c] = col_pref[r][c] + v
                pref[r + 1][c + 1] = pref[r][c + 1] + run

        for r0 in range(h - 1):
            for r1 in range(r0 + 1, h):
                rh = r1 - r0 + 1
                for c0 in range(w - 1):
                    for c1 in range(c0 + 1, w):
                        cw = c1 - c0 + 1
                        area = rh * cw
                        n = (pref[r1 + 1][c1 + 1] - pref[r0][c1 + 1]
                             - pref[r1 + 1][c0] + pref[r0][c0])
                        if n < 4 or n / area < 0.55:
                            continue
                        # A patch should leave some trace in each of its rows and columns.
                        if any(row_pref[r][c1 + 1] == row_pref[r][c0]
                               for r in range(r0, r1 + 1)):
                            continue
                        if any(col_pref[r1 + 1][c] == col_pref[r0][c]
                               for c in range(c0, c1 + 1)):
                            continue
                        score = n - 0.18 * (area - n) + 0.02 * area
                        candidates.append((score, n, area, color, r0, r1, c0, c1))

    candidates.sort(reverse=True)
    patches = []
    for cand in candidates:
        _, _, _, _, r0, r1, c0, c1 = cand
        if any(not (r1 < p[4] or r0 > p[5] or c1 < p[6] or c0 > p[7])
               for p in patches):
            continue
        patches.append(cand)

    # Occasionally a patch loses an entire edge row. If a narrow patch shares
    # its top edge with a nearby, taller rectangular patch, restore that aligned edge.
    bounds = [list(p[4:8]) + [p[3]] for p in patches]  # r0,r1,c0,c1,color
    for i, a in enumerate(bounds):
        r0, r1, c0, c1, color = a
        if c1 - c0 + 1 > 3:
            continue
        for b in bounds:
            br0, br1, bc0, bc1, bcolor = b
            gap = max(0, max(c0, bc0) - min(c1, bc1) - 1)
            if bcolor != color and br0 == r0 and br1 > r1 and br1 - r1 <= 2 and gap <= 3:
                a[1] = br1
                break

    out = [[bg] * w for _ in range(h)]
    for r0, r1, c0, c1, color in bounds:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color
    return out

